const input = $json || {};
const body = (input.body && typeof input.body === 'object') ? input.body : input;
const cfgNode = $item(0).$node['Config'].json;
const cfg = {
  locationId: cfgNode.locationId,
  ghlApiBaseUrl: cfgNode.ghlApiBaseUrl,
  ghlApiKey: cfgNode.ghlApiKey,
  apolloApiBaseUrl: cfgNode.apolloApiBaseUrl,
  apolloApiKey: cfgNode.apolloApiKey,
  sheetId: cfgNode.sheetId,
  sheetGid: cfgNode.sheetGid || '0',
  gateFieldKey: cfgNode.gateFieldKey,
  gateYesValues: String(cfgNode.gateYesValues || 'yes,true,1').split(',').map(v => v.trim().toLowerCase()).filter(Boolean),
};

if (!cfg.locationId) throw new Error('Missing Config.locationId');
if (!cfg.ghlApiKey) throw new Error('Missing Config.ghlApiKey');

const contactId = body.contactId || body.contact?.id || body.id || body.contact_id;
if (!contactId) throw new Error('Missing contactId in webhook payload');

function norm(v) { return String(v ?? '').trim().toLowerCase(); }
function asArr(v) { return Array.isArray(v) ? v : []; }
function strOrNull(v) { const s = String(v ?? '').trim(); return s ? s : null; }
function numOrNull(v) { if (v === null || v === undefined || v === '') return null; const clean = String(v).replace(/[^0-9.-]/g, ''); const n = Number(clean); return Number.isFinite(n) ? n : null; }
function dateOrNull(v) { if (!v) return null; const d = new Date(v); return isNaN(d.getTime()) ? null : d.toISOString().slice(0,10); }
function keyify(v) { return String(v ?? '').trim().toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, ''); }
function pick(rec, aliases) {
  for (const alias of aliases) {
    for (const [k, v] of Object.entries(rec || {})) {
      if (keyify(k) === keyify(alias)) {
        const s = String(v ?? '').trim();
        if (s !== '') return s;
      }
    }
  }
  return null;
}

async function doHttpRequest(options) {
  if (typeof $httpRequest === 'function') return await $httpRequest(options);
  if (this?.helpers?.httpRequest) return await this.helpers.httpRequest(options);
  throw new Error('HTTP helper not available');
}

async function apiRequest({ baseUrl, method, path, headers, body, fullUrl, json = true }) {
  const options = {
    method,
    url: fullUrl || `${String(baseUrl).replace(/\/$/, '')}${path}`,
    headers,
    json,
  };
  if (body !== undefined) options.body = body;
  try {
    const data = await doHttpRequest.call(this, options);
    return { ok: true, status: 200, data };
  } catch (err) {
    return { ok: false, status: err?.statusCode || err?.httpCode || err?.cause?.statusCode || 500, data: err?.response?.body || err?.message || err, requestBody: body };
  }
}

const ghlHeaders = {
  Authorization: `Bearer ${cfg.ghlApiKey}`,
  Version: '2021-07-28',
  'Content-Type': 'application/json',
  Accept: 'application/json',
};

const contactRes = await apiRequest.call(this, {
  baseUrl: cfg.ghlApiBaseUrl,
  method: 'GET',
  path: `/contacts/${contactId}`,
  headers: ghlHeaders,
});
if (!contactRes.ok) throw new Error(`Failed to fetch GHL contact ${contactId}: ${contactRes.status} ${JSON.stringify(contactRes.data)}`);
const contact = contactRes.data?.contact || contactRes.data || {};

if (cfg.gateFieldKey) {
  const payloadGateVal = body[cfg.gateFieldKey] ?? body.gateValue ?? body.getApolloEnrichment;
  if (payloadGateVal !== undefined && !cfg.gateYesValues.includes(norm(payloadGateVal))) {
    return [{ json: { ok: true, skipped: true, reason: `Gate not satisfied: ${cfg.gateFieldKey}=${payloadGateVal}`, contactId } }];
  }
}

const contactEmail = norm(body.email || contact.email);

const fieldsRes = await apiRequest.call(this, {
  baseUrl: cfg.ghlApiBaseUrl,
  method: 'GET',
  path: `/locations/${cfg.locationId}/customFields?model=contact`,
  headers: ghlHeaders,
});
if (!fieldsRes.ok) throw new Error(`Failed to fetch custom fields: ${fieldsRes.status} ${JSON.stringify(fieldsRes.data)}`);

const customFields = Array.isArray(fieldsRes.data?.customFields)
  ? fieldsRes.data.customFields
  : Array.isArray(fieldsRes.data?.data?.customFields)
    ? fieldsRes.data.data.customFields
    : Array.isArray(fieldsRes.data?.data)
      ? fieldsRes.data.data
      : [];
const fieldByName = new Map(customFields.map((f) => [String(f.name || '').trim(), f]));

function parseCsv(text) {
  const rows = [];
  let row = [];
  let cell = '';
  let inQuotes = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    const next = text[i + 1];
    if (inQuotes) {
      if (ch === '"' && next === '"') { cell += '"'; i++; }
      else if (ch === '"') { inQuotes = false; }
      else { cell += ch; }
    } else {
      if (ch === '"') inQuotes = true;
      else if (ch === ',') { row.push(cell); cell = ''; }
      else if (ch === '\n') { row.push(cell); rows.push(row); row = []; cell = ''; }
      else if (ch === '\r') { }
      else { cell += ch; }
    }
  }
  if (cell.length || row.length) { row.push(cell); rows.push(row); }
  return rows;
}

function mapSheetStandard(rec) {
  return {
    firstName: pick(rec, ['First Name', 'first_name']),
    lastName: pick(rec, ['Last Name', 'last_name']),
    email: pick(rec, ['Email', 'email']),
    phone: pick(rec, ['Phone', 'Mobile Phone', 'Work Direct Phone', 'Corporate Phone']),
    companyName: pick(rec, ['Company Name', 'company_name']),
    address1: pick(rec, ['Address', 'Company Address']),
    city: pick(rec, ['City', 'Company City']),
    state: pick(rec, ['State', 'Company State']),
    country: pick(rec, ['Country', 'Company Country']),
  };
}

function mapSheetCustom(rec) {
  return {
    'Title': pick(rec, ['Title']),
    'Company Name for Emails': pick(rec, ['Company Name for Emails']),
    'Corporate Phone': pick(rec, ['Corporate Phone']),
    'Company Phone': pick(rec, ['Company Phone']),
    'Lists': pick(rec, ['Lists']),
    'Batch_Upload': pick(rec, ['Batch_Upload']),

    'Apollo Contact Id': pick(rec, ['Apollo Contact Id']),
    'Apollo Account Id': pick(rec, ['Apollo Account Id']),
    'Apollo Email Status': pick(rec, ['Apollo Email Status', 'Email Status']),
    'Apollo Primary Email Source': pick(rec, ['Apollo Primary Email Source', 'Primary Email Source']),
    'Apollo Primary Email Verification Source': pick(rec, ['Apollo Primary Email Verification Source', 'Primary Email Verification Source']),
    'Apollo Email Confidence': numOrNull(pick(rec, ['Apollo Email Confidence', 'Email Confidence'])),
    'Apollo Primary Email Catch-all Status': pick(rec, ['Apollo Primary Email Catch-all Status', 'Primary Email Catch-all Status']),
    'Apollo Primary Email Last Verified At': dateOrNull(pick(rec, ['Apollo Primary Email Last Verified At', 'Primary Email Last Verified At'])),
    'Apollo Seniority': pick(rec, ['Apollo Seniority', 'Seniority']),
    'Apollo Departments': pick(rec, ['Apollo Departments', 'Departments']),
    'Apollo Sub Departments': pick(rec, ['Apollo Sub Departments', 'Sub Departments']),
    'Apollo Company Employees': numOrNull(pick(rec, ['Apollo Company Employees', '# Employees'])),
    'Apollo Industry': pick(rec, ['Apollo Industry', 'Industry']),
    'Apollo Keywords': pick(rec, ['Apollo Keywords', 'Keywords']),
    'Apollo Person LinkedIn URL': pick(rec, ['Apollo Person LinkedIn URL', 'Person Linkedin Url']),
    'Apollo Company LinkedIn URL': pick(rec, ['Apollo Company LinkedIn URL', 'Company Linkedin Url']),
    'Apollo Facebook URL': pick(rec, ['Apollo Facebook URL', 'Facebook Url']),
    'Apollo Twitter URL': pick(rec, ['Apollo Twitter URL', 'Twitter Url']),
    'Apollo Technologies': pick(rec, ['Apollo Technologies', 'Technologies']),
    'Apollo Annual Revenue': numOrNull(pick(rec, ['Apollo Annual Revenue', 'Annual Revenue'])),
    'Apollo Total Funding': numOrNull(pick(rec, ['Apollo Total Funding', 'Total Funding'])),
    'Apollo Latest Funding': pick(rec, ['Apollo Latest Funding', 'Latest Funding']),
    'Apollo Latest Funding Amount': numOrNull(pick(rec, ['Apollo Latest Funding Amount', 'Latest Funding Amount'])),
    'Apollo Last Raised At': dateOrNull(pick(rec, ['Apollo Last Raised At', 'Last Raised At'])),
    'Apollo Subsidiary Of': pick(rec, ['Apollo Subsidiary Of', 'Subsidiary of']),
    'Apollo Secondary Email': pick(rec, ['Apollo Secondary Email', 'Secondary Email']),
    'Apollo Secondary Email Source': pick(rec, ['Apollo Secondary Email Source', 'Secondary Email Source']),
    'Apollo Secondary Email Status': pick(rec, ['Apollo Secondary Email Status', 'Secondary Email Status']),
    'Apollo Secondary Email Verification Source': pick(rec, ['Apollo Secondary Email Verification Source', 'Secondary Email Verification Source']),
    'Apollo Tertiary Email': pick(rec, ['Apollo Tertiary Email', 'Tertiary Email']),
    'Apollo Tertiary Email Source': pick(rec, ['Apollo Tertiary Email Source', 'Tertiary Email Source']),
    'Apollo Tertiary Email Status': pick(rec, ['Apollo Tertiary Email Status', 'Tertiary Email Status']),
    'Apollo Tertiary Email Verification Source': pick(rec, ['Apollo Tertiary Email Verification Source', 'Tertiary Email Verification Source']),
    'Apollo Primary Intent Topic': pick(rec, ['Apollo Primary Intent Topic', 'Primary Intent Topic']),
    'Apollo Primary Intent Score': numOrNull(pick(rec, ['Apollo Primary Intent Score', 'Primary Intent Score'])),
    'Apollo Secondary Intent Topic': pick(rec, ['Apollo Secondary Intent Topic', 'Secondary Intent Topic']),
    'Apollo Secondary Intent Score': numOrNull(pick(rec, ['Apollo Secondary Intent Score', 'Secondary Intent Score'])),
    'Apollo Qualify Contact': pick(rec, ['Apollo Qualify Contact', 'Qualify Contact']),
  };
}

function mapApolloToCustom(person) {
  const org = person.organization || {};
  const mapping = {
    'Apollo Contact Id': person.id || null,
    'Apollo Account Id': org.id || person.organization_id || null,
    'Apollo Email Status': person.email_status || null,
    'Apollo Primary Email Source': null,
    'Apollo Primary Email Verification Source': null,
    'Apollo Email Confidence': numOrNull(person.extrapolated_email_confidence),
    'Apollo Primary Email Catch-all Status': null,
    'Apollo Primary Email Last Verified At': null,
    'Apollo Seniority': person.seniority || null,
    'Apollo Departments': asArr(person.departments).join(', ') || null,
    'Apollo Sub Departments': asArr(person.subdepartments).join(', ') || null,
    'Apollo Company Employees': numOrNull(org.estimated_num_employees),
    'Apollo Industry': org.industry || null,
    'Apollo Keywords': asArr(org.keywords).join(', ') || null,
    'Apollo Person LinkedIn URL': person.linkedin_url || null,
    'Apollo Company LinkedIn URL': org.linkedin_url || null,
    'Apollo Facebook URL': person.facebook_url || org.facebook_url || null,
    'Apollo Twitter URL': person.twitter_url || org.twitter_url || null,
    'Apollo Technologies': asArr(org.technology_names).join(', ') || null,
    'Apollo Annual Revenue': numOrNull(org.annual_revenue),
    'Apollo Total Funding': numOrNull(org.total_funding),
    'Apollo Latest Funding': org.latest_funding_stage || null,
    'Apollo Latest Funding Amount': null,
    'Apollo Last Raised At': dateOrNull(org.latest_funding_round_date),
    'Apollo Subsidiary Of': null,
    'Apollo Secondary Email': null,
    'Apollo Secondary Email Source': null,
    'Apollo Secondary Email Status': null,
    'Apollo Secondary Email Verification Source': null,
    'Apollo Tertiary Email': null,
    'Apollo Tertiary Email Source': null,
    'Apollo Tertiary Email Status': null,
    'Apollo Tertiary Email Verification Source': null,
    'Apollo Primary Intent Topic': null,
    'Apollo Primary Intent Score': null,
    'Apollo Secondary Intent Topic': null,
    'Apollo Secondary Intent Score': null,
    'Apollo Qualify Contact': null,
  };
  if (Array.isArray(org.funding_events) && org.funding_events.length) {
    const latestEvent = org.funding_events
      .map((e) => ({ e, ts: new Date(e?.date || 0).getTime() || 0 }))
      .sort((a, b) => b.ts - a.ts)[0]?.e;
    if (latestEvent?.amount) mapping['Apollo Latest Funding Amount'] = numOrNull(latestEvent.amount);
  }
  return mapping;
}

function mapApolloToStandard(person) {
  const org = person.organization || {};
  return {
    firstName: strOrNull(person.first_name),
    lastName: strOrNull(person.last_name),
    email: strOrNull(person.email),
    companyName: strOrNull(org.name),
    city: strOrNull(org.city),
    state: strOrNull(org.state),
    country: strOrNull(org.country),
  };
}

async function updateContactWithData({ standard = {}, custom = {}, source }) {
  const standardClean = {};
  for (const [k, v] of Object.entries(standard || {})) {
    if (v !== null && v !== undefined && String(v).trim() !== '') standardClean[k] = v;
  }

  const customUpdates = [];
  for (const [fieldName, value] of Object.entries(custom || {})) {
    if (value === null || value === undefined || String(value).trim() === '') continue;
    const f = fieldByName.get(fieldName);
    if (!f?.id) continue;
    customUpdates.push({ id: f.id, value });
  }

  if (!Object.keys(standardClean).length && !customUpdates.length) {
    return { ok: true, skipped: true, reason: `No mapped values from ${source}`, source };
  }

  const customFieldObject = Object.fromEntries(customUpdates.map((u) => [u.id, u.value]));
  const customFieldArray = customUpdates.map((u) => ({ id: u.id, value: u.value }));

  const bodies = [];
  if (customUpdates.length) {
    bodies.push({ ...standardClean, locationId: cfg.locationId, customField: customFieldObject });
    bodies.push({ ...standardClean, customField: customFieldObject });
    bodies.push({ ...standardClean, locationId: cfg.locationId, customFields: customFieldArray });
    bodies.push({ ...standardClean, customFields: customFieldArray });
    bodies.push({ ...standardClean, locationId: cfg.locationId, customFields: customUpdates.map((u) => ({ id: u.id, field_value: u.value })) });
    bodies.push({ ...standardClean, customFields: customUpdates.map((u) => ({ id: u.id, field_value: u.value })) });
  } else {
    bodies.push({ ...standardClean, locationId: cfg.locationId });
    bodies.push({ ...standardClean });
  }

  let usedBody = null;
  let lastErr = null;
  for (const bodyTry of bodies) {
    const r = await apiRequest.call(this, {
      baseUrl: cfg.ghlApiBaseUrl,
      method: 'PUT',
      path: `/contacts/${contactId}`,
      headers: ghlHeaders,
      body: bodyTry,
    });
    if (r.ok) {
      usedBody = bodyTry;
      break;
    }
    lastErr = { status: r.status, data: r.data, body: bodyTry };
  }

  if (!usedBody) throw new Error(`Failed updating contact from ${source}: ${JSON.stringify(lastErr)}`);

  return {
    ok: true,
    source,
    updatedStandardFields: Object.keys(standardClean),
    updatedCustomFieldCount: customUpdates.length,
    updatedCustomFieldIds: customUpdates.map((u) => u.id),
    updateRequestBodyUsed: usedBody,
  };
}

let sheetChecked = false;
let sheetMatched = false;
let sheetMatchMeta = null;

if (cfg.sheetId && contactEmail) {
  sheetChecked = true;
  const csvUrl = `https://docs.google.com/spreadsheets/d/${cfg.sheetId}/export?format=csv&gid=${encodeURIComponent(cfg.sheetGid)}`;
  const csvRes = await apiRequest.call(this, { method: 'GET', fullUrl: csvUrl, headers: { Accept: 'text/csv' }, json: false });

  if (csvRes.ok) {
    const text = typeof csvRes.data === 'string' ? csvRes.data : String(csvRes.data || '');
    const rows = parseCsv(text);
    if (rows.length > 1) {
      const headers = rows[0];
      const dataRows = rows.slice(1);
      const keyMap = headers.map((h) => keyify(h));
      const primaryEmailIdx = keyMap.indexOf('email');
      const secondaryEmailIdx = keyMap.indexOf('apollo_secondary_email') >= 0
        ? keyMap.indexOf('apollo_secondary_email')
        : keyMap.indexOf('secondary_email');

      for (let i = 0; i < dataRows.length; i++) {
        const r = dataRows[i];
        const primary = norm(primaryEmailIdx >= 0 ? r[primaryEmailIdx] : '');
        const secondary = norm(secondaryEmailIdx >= 0 ? r[secondaryEmailIdx] : '');
        if (contactEmail && (contactEmail === primary || contactEmail === secondary)) {
          const rec = {};
          headers.forEach((h, idx) => { rec[h] = r[idx] ?? ''; });

          const standard = mapSheetStandard(rec);
          const custom = mapSheetCustom(rec);
          const upd = await updateContactWithData.call(this, { standard, custom, source: 'google_sheet' });

          sheetMatched = true;
          sheetMatchMeta = {
            rowNumber: i + 2,
            primaryEmail: primaryEmailIdx >= 0 ? (r[primaryEmailIdx] || '') : '',
            secondaryEmail: secondaryEmailIdx >= 0 ? (r[secondaryEmailIdx] || '') : '',
            ...upd,
          };
          break;
        }
      }
    }
  }
}

if (sheetMatched) {
  return [{ json: { ok: true, contactId, source: 'google_sheet', sheetChecked, sheetMatched, ...sheetMatchMeta } }];
}

if (!cfg.apolloApiKey) throw new Error('No Google Sheet match and missing Apollo API key for fallback');

const apolloHeaders = {
  'X-Api-Key': cfg.apolloApiKey,
  'Content-Type': 'application/json',
  'Cache-Control': 'no-cache',
  Accept: 'application/json',
};

const email = strOrNull(body.email || contact.email);
const firstName = strOrNull(body.firstName || body.first_name || contact.firstName || contact.first_name);
const lastName = strOrNull(body.lastName || body.last_name || contact.lastName || contact.last_name);
const organizationName = strOrNull(body.organization_name || body.companyName || body.company || contact.companyName || contact.company);
const linkedinUrl = strOrNull(body.linkedin_url || body.linkedinUrl || contact.website || null);
const domain = strOrNull(body.domain || (organizationName && organizationName.includes('.') ? organizationName : null));

if (!email && !linkedinUrl && !(firstName && lastName && (organizationName || domain))) {
  throw new Error('No Google Sheet match and insufficient data for Apollo people/match');
}

const apolloBody = {
  first_name: firstName || undefined,
  last_name: lastName || undefined,
  organization_name: organizationName || undefined,
  email: email || undefined,
  domain: domain || undefined,
  linkedin_url: linkedinUrl || undefined,
  reveal_personal_emails: false,
  reveal_phone_number: false,
};
Object.keys(apolloBody).forEach((k) => apolloBody[k] === undefined && delete apolloBody[k]);

const apolloRes = await apiRequest.call(this, {
  baseUrl: cfg.apolloApiBaseUrl,
  method: 'POST',
  path: '/v1/people/match',
  headers: apolloHeaders,
  body: apolloBody,
});
if (!apolloRes.ok) throw new Error(`Apollo people/match failed: ${apolloRes.status} ${JSON.stringify(apolloRes.data)}`);

const person = apolloRes.data?.person;
if (!person) throw new Error(`Apollo response missing person object: ${JSON.stringify(apolloRes.data)}`);

const apolloStandard = mapApolloToStandard(person);
const apolloCustom = mapApolloToCustom(person);
const apolloUpdate = await updateContactWithData.call(this, { standard: apolloStandard, custom: apolloCustom, source: 'apollo' });

return [{ json: { ok: true, contactId, source: 'apollo', sheetChecked, sheetMatched, apolloPersonId: person.id || null, ...apolloUpdate } }];
